@Value("${app.name}")        // PLACEHOLDER - podstawia gotowa wartosc z konfiguracji
@Value("#{10 * 5}")          // SpEL - WYLICZA wyrazenie, wynik: 50
@Value("#{appConfig.limit}") // SpEL - odwolanie do WLASCIWOSCI innego beana

ExpressionParser parser = new SpelExpressionParser();

Integer result = (Integer) parser.parseExpression("10 * (2 + 3)").getValue();
System.out.println(result); // 25

String upper = (String) parser.parseExpression("'Ala ma kota'.toUpperCase()").getValue();
System.out.println(upper); // ALA MA KOTA - SpEL wywolal PRAWDZIWA metode Javy

StandardEvaluationContext evaluationContext = new StandardEvaluationContext();
evaluationContext.setVariable("policy", new DiscountPolicy());

Double discount = (Double) parser
    .parseExpression("#policy.discountFor(250.0)")
    .getValue(evaluationContext);
// SpEL wywolal metode discountFor() na obiekcie DiscountPolicy przekazanym jako "#policy"
